# নবম-দশম সাধারণ গণিত, অধ্যায় ২ (সেট ও ফাংশন): মৌলিক সংক্ষিপ্ত প্রশ্ন (অনুশীলনী ২.১ ও ২.২)
# উত্তরগুলো নিচের assert দিয়ে যাচাই করা। চালালে src/sq/c10_2.json লেখে।
import json, os
from fractions import Fraction as F
from itertools import combinations
S=lambda *a:set(a)
# ---- যাচাই ----
assert {x for x in range(1,50) if x*x<30}=={1,2,3,4,5}
assert {x for x in range(-10,10) if -2<x<=3}=={-1,0,1,2,3}
assert sum(1 for r in range(4) for _ in combinations('abc',r))==8
assert 2**5==32 and 2**6==64
A,B={2,4,6,8},{4,8,12}; assert A|B=={2,4,6,8,12} and A&B=={4,8}
A,B={1,2,3,4,5},{2,4,6}; assert A-B=={1,3,5} and B-A=={6}
U=set(range(1,9)); assert U-{2,3,5,7}=={1,4,6,8}
U=set(range(1,7)); A,B={1,2,3},{2,4,6}; assert U-(A|B)==(U-A)&(U-B)=={5}
assert {x for x in range(1,13) if 12%x==0}=={1,2,3,4,6,12}
A={x for x in range(1,20) if 2<x<7}; B={x for x in range(1,20) if x%2==0 and x<=8}; assert A&B=={4,6}
assert 20+15-6==29 and 25+20-40==5
A,B,C={1,2,3},{2,3,4},{3,4,5}; assert A&(B|C)=={2,3}
A,B,C={1,2},{2,3},{3}; P=lambda X,Y:{(x,y) for x in X for y in Y}; assert P(A,B)&P(A,C)=={(1,3),(2,3)}
f=lambda x:x*x-3*x+2; assert f(3)==2 and f(-1)==6
assert 3*4-5==7
f=lambda x:x*x+1; assert f(2)+f(-2)==10
f=lambda x:2*x+3; assert f(f(1))==13
f=lambda x:F(1)/(x+1); assert f(F(1,2))==F(2,3)
assert {x*x for x in (-1,0,1)}=={0,1}
assert (4*2-1)*((-3)**2)==63
f=lambda x:F(x+1,x-1); assert f(2)+f(3)==5
A=[1,2,3,4]; assert [(x,y) for x in A for y in A if x+y==5]==[(1,4),(2,3),(3,2),(4,1)]
A=[-2,-1,0,1,2]; R=[(x,y) for x in A for y in A if y==x*x]; assert R==[(-1,1),(0,0),(1,1)]
assert all(x*x-5*x+6==0 for x in (2,3))
